import * as THREE from 'three';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x708b73);scene.fog=new THREE.FogExp2(0x708b73,.009);
const camera=new THREE.OrthographicCamera(-16,16,9,-9,.1,500);
camera.position.set(0,7,28);camera.lookAt(0,3,0);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const hemi=new THREE.HemisphereLight(0xd9e8d0,0x293628,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffe6b2,3.2);sun.position.set(-12,23,16);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-24;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight(0x84b9b4,1.25);fill.position.set(12,9,-15);scene.add(fill);
const materials={ground:mat(0x4b5638),dirt:mat(0x66513b),grass:mat(0x60764a),leaf:mat(0x496b43),leaf2:mat(0x6a824a),trunk:mat(0x554331),fern:mat(0x567d4a),stone:mat(0x73766a),water:new THREE.MeshStandardMaterial({color:0x427e7d,roughness:.27,metalness:.12,transparent:true,opacity:.83}),wood:mat(0x815b3b),bark:mat(0x4d402e),camp:mat(0xffa64d,0,.4),metal:mat(0x70786f,.55),cloth:mat(0x899277),skin:mat(0xc89165),dark:mat(0x282d26)};
function mat(color,metalness=0,roughness=.85){return new THREE.MeshStandardMaterial({color,metalness,roughness})}
function mesh(geo,material,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,x,y,z,sx,sy,sz,material){return mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent,x,y,z)}
function ellipsoid(parent,x,y,z,sx,sy,sz,material){const m=mesh(new THREE.SphereGeometry(1,12,9),material,parent,x,y,z);m.scale.set(sx,sy,sz);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=8){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent,x,y,z)}
const world=new THREE.Group();scene.add(world);
const ground=mesh(new THREE.PlaneGeometry(620,72,1,1),materials.ground,world,80,-.5,-1);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;
const dirtLayer=mesh(new THREE.BoxGeometry(620,.8,72),materials.dirt,world,80,-1,-1);dirtLayer.receiveShadow=true;
// distant ridge and layered jungle silhouette
for(let i=0;i<30;i++){const x=-100+i*13;const h=4+Math.random()*9;const ridge=mesh(new THREE.ConeGeometry(9,h,5),mat(i%2?0x52654d:0x405646),world,x,h*.45,-35);ridge.scale.z=.45;ridge.castShadow=false;}
for(let i=0;i<44;i++){const x=-110+i*7.7;const h=4+Math.random()*7;const tree=new THREE.Group();tree.position.set(x,0,-15-Math.random()*8);world.add(tree);cylinder(tree,0,h*.42,0,.3,.55,h*.85,materials.trunk);const top=ellipsoid(tree,0,h*.85,0,2.5,2.8,1.4,i%3?materials.leaf:materials.leaf2);top.castShadow=false;for(let b=0;b<3;b++){const branch=cylinder(tree,(Math.random()-.5)*1.6,h*.68,(Math.random()-.5)*.8,.12,.19,2,materials.trunk);branch.rotation.z=(Math.random()-.5)*1.2;}}
// distant waterfall and river band
const river=mesh(new THREE.PlaneGeometry(40,8),materials.water,world,90,-.05,-9);river.rotation.x=-Math.PI/2;river.rotation.z=-.12;
const falls=mesh(new THREE.PlaneGeometry(4,8),new THREE.MeshStandardMaterial({color:0x93c5bc,transparent:true,opacity:.65,roughness:.2}),world,85,3,-14);falls.position.z=-14;
// island set pieces
function makeTree(x,z=2,size=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(size);world.add(g);const height=4.5+Math.random()*2.2;cylinder(g,0,height/2,0,.3,.48,height,materials.trunk);ellipsoid(g,0,height*.9,0,1.75,2.2,1.35,materials.leaf);ellipsoid(g,-.9,height*.82,.2,1.2,1.5,1.1,materials.leaf2);ellipsoid(g,.9,height*.83,-.2,1.15,1.4,1,materials.leaf);for(let n=0;n<5;n++){const twig=cylinder(g,(Math.random()-.5)*1.7,height*.7,(Math.random()-.5)*.5,.1,.17,2,materials.trunk);twig.rotation.z=(Math.random()-.5)*1.4;}return g}
function makeFern(x,z=3){const g=new THREE.Group();g.position.set(x,.05,z);world.add(g);for(let j=0;j<7;j++){const a=j*Math.PI*2/7;const stalk=cylinder(g,Math.cos(a)*.35,.8,Math.sin(a)*.35,.035,.065,1.6,materials.fern);stalk.rotation.z=Math.cos(a)*.7;stalk.rotation.x=Math.sin(a)*.4;for(let k=0;k<4;k++){const leaf=ellipsoid(g,Math.cos(a)*(.4+k*.22),.35+k*.22,Math.sin(a)*(.4+k*.2),.12,.42,.18,k%2?materials.fern:materials.leaf);leaf.rotation.z=-Math.cos(a)*.5;leaf.rotation.y=a;}}}
function makeRock(x,z=2,size=1){const r=mesh(new THREE.DodecahedronGeometry(size,0),materials.stone,world,x,size*.5,z);r.scale.set(1.3,.8,.9);r.rotation.set(Math.random()*.3,Math.random()*2,Math.random()*.3);return r}
for(let x=-100;x<250;x+=11+Math.random()*8){makeTree(x,1+Math.random()*4,.7+Math.random()*.7);for(let j=0;j<4;j++)makeFern(x+(Math.random()-.5)*8,2+Math.random()*3)}
// broken research station in the far field
const lab=new THREE.Group();lab.position.set(120,0,-1);world.add(lab);box(lab,0,2,0,8,4,5,mat(0x59645b));box(lab,-1,4,0,8.5,.35,5.5,mat(0x626e62));box(lab,2,1.3,2.56,1.4,2.4,.08,mat(0x263936));box(lab,-2,2.5,2.58,2,.75,.1,mat(0x76988a));box(lab,-2,2.5,2.5,1.8,.08,.08,mat(0x334941));box(lab,-2,2.5,2.5,.08,.7,.08,mat(0x334941));
for(let x=-94;x<220;x+=6+Math.random()*6){if(Math.random()<.54)makeRock(x,3,Math.random()*.8+.3)}
// wet ground detail and grass blades
for(let i=0;i<180;i++){const x=-110+Math.random()*340,z=1+Math.random()*8;const tuft=new THREE.Group();tuft.position.set(x,0,z);world.add(tuft);for(let j=0;j<3;j++){const blade=mesh(new THREE.ConeGeometry(.12,.7,4),j%2?materials.fern:materials.grass,tuft,(Math.random()-.5)*.5,.35,(Math.random()-.5)*.5);blade.rotation.z=(Math.random()-.5)*.6;blade.castShadow=false;}}
// camp is a lasting landmark
const camp=new THREE.Group();camp.position.set(-12,0,1);world.add(camp);for(let i=0;i<3;i++){const log=cylinder(camp,(i-1)*.35,.2,0,.09,.09,1.8,materials.wood,7);log.rotation.z=Math.PI/2;log.rotation.y=i*Math.PI/3;}const flame=ellipsoid(camp,0,.55,0,.2,.4,.2,materials.camp);const fireLight=new THREE.PointLight(0xffa457,0,9);fireLight.position.set(-12,.8,1);world.add(fireLight);

const resources=[];
function addResource(type,x,z=2){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);if(type==='wood'){cylinder(g,0,.22,0,.12,.12,1.5,materials.wood,7).rotation.z=Math.PI/2;ellipsoid(g,.55,.16,0,.2,.15,.15,materials.bark);}if(type==='stone'){const r=mesh(new THREE.DodecahedronGeometry(.42,0),materials.stone,g,0,.35,0);r.scale.set(1.2,.8,1);}if(type==='berries'){const bush=ellipsoid(g,0,.45,0,.6,.48,.5,materials.leaf2);for(let i=0;i<6;i++)ellipsoid(g,(Math.random()-.5)*.8,.4+Math.random()*.5,(Math.random()-.5)*.7,.1,.1,.1,mat(0xb24e3d));}if(type==='fiber'){for(let i=0;i<5;i++){const leaf=ellipsoid(g,(i-2)*.13,.45,0,.12,.55,.11,materials.fern);leaf.rotation.z=(i-2)*.16;}}if(type==='crate'){box(g,0,.55,0,1.1,1.1,.9,mat(0x77734d));for(let yy=.15;yy<1;yy+=.3)box(g,0,yy,.47,1.12,.07,.07,materials.wood);box(g,0,.55,.48,.08,1.1,.07,materials.wood);}resources.push({type,x,z,group:g,active:true});}
for(let i=0;i<30;i++){const x=-65+i*9+Math.random()*4;addResource(['wood','stone','berries','fiber'][Math.floor(Math.random()*4)],x,1.7+Math.random()*3)}
addResource('crate',53,1.8);addResource('crate',126,2);

const player=new THREE.Group();world.add(player);player.position.set(0,0,2);player.rotation.y=0;
const body=new THREE.Group();player.add(body);
const torso=ellipsoid(body,0,1.42,0,.38,.55,.25,materials.cloth);const jacket=box(body,0,1.48,0,.58,.72,.44,mat(0x6c755f));
ellipsoid(body,0,2.05,0,.25,.29,.24,materials.skin);ellipsoid(body,.01,2.2,-.01,.26,.18,.25,mat(0x3a4034));box(body,.09,2.07,.2,.07,.08,.035,mat(0x252b27));
const backpack=box(body,-.36,1.48,-.02,.25,.5,.34,mat(0x795b3b));box(body,-.37,1.49,.18,.17,.22,.07,mat(0x9b7950));
const limbs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.17,1.05,0);body.add(leg);cylinder(leg,0,-.37,0,.12,.15,.72,mat(0x465147));box(leg,0,-.74,.06,.21,.14,.36,mat(0x40382e));limbs.push(leg);const arm=new THREE.Group();arm.position.set(side*.35,1.7,0);body.add(arm);cylinder(arm,0,-.28,0,.1,.12,.52,materials.skin);ellipsoid(arm,0,-.02,0,.14,.16,.13,mat(0x6c755f));limbs.push(arm);}
// held spear is a recognizable 3D tool
const held=new THREE.Group();held.position.set(.5,1.1,.24);body.add(held);cylinder(held,0,.42,0,.035,.035,1.2,materials.wood);const spearTip=mesh(new THREE.ConeGeometry(.09,.28,5),materials.stone,held,0,1.12,0);spearTip.rotation.z=0;

const dinos=[];
function makeDino(species,x,z=0){const group=new THREE.Group();group.position.set(x,0,z);world.add(group);const scale={rex:1.55,raptor:.82,triceratops:1.35,stegosaurus:1.3,brachiosaurus:1.7,pteranodon:.8}[species]||1;group.scale.setScalar(scale);const skin=mat(({rex:0x765548,raptor:0x6d7955,triceratops:0x747c59,stegosaurus:0x62765b,brachiosaurus:0x788463,pteranodon:0x635c50})[species]||0x738064);const belly=mat(0xb3a282);const d=new THREE.Group();group.add(d);
if(species==='pteranodon'){ellipsoid(d,0,2,0,.45,.26,.3,skin);ellipsoid(d,.43,2.12,.03,.35,.13,.14,skin);const beak=mesh(new THREE.ConeGeometry(.13,.75,5),belly,d,.76,2.12,0);beak.rotation.z=-Math.PI/2;for(const s of [-1,1]){const wing=mesh(new THREE.ConeGeometry(.34,2.8,4),skin,d,s*.85,1.8,s*.28);wing.rotation.z=s*.16;wing.rotation.x=s*.15;}}
else{ellipsoid(d,-.05,1,0,.85,.58,.4,skin);ellipsoid(d,.45,1.05,.05,.64,.3,.36,belly);if(species==='brachiosaurus'){const neck=cylinder(d,.53,2.05,0,.28,.42,2.5,skin,9);neck.rotation.z=-.18;ellipsoid(d,.42,3.35,0,.42,.32,.35,skin);ellipsoid(d,.75,3.35,.03,.26,.17,.22,belly);}else{const neck=ellipsoid(d,.58,1.55,0,.55,.26,.28,skin);neck.rotation.z=-.35;ellipsoid(d,1.03,1.62,0,.33,.23,.27,skin);ellipsoid(d,1.2,1.54,.18,.06,.05,.04,mat(0x1e211c));if(species==='triceratops'){for(let k=0;k<3;k++){const horn=mesh(new THREE.ConeGeometry(.07,.55,5),belly,d,.99+(k===2?.22:0),1.85-(k===2?.08:0),(k-1)*.22);horn.rotation.z=-.7;}ellipsoid(d,.82,1.85,0,.42,.37,.09,belly);}if(species==='rex'){const jaw=ellipsoid(d,1.12,1.42,.02,.28,.09,.24,belly);for(let i=0;i<4;i++){const tooth=mesh(new THREE.ConeGeometry(.035,.12,4),mat(0xf0dfbb),d,.98+i*.1,1.38,.2);tooth.rotation.z=Math.PI;}}}
if(species==='stegosaurus'){for(let i=0;i<6;i++){const p=mesh(new THREE.ConeGeometry(.24,.65,4),mat(0x9a8b61),d,-.65+i*.23,1.55+(i%2)*.07,0);p.rotation.z=Math.PI;}for(let s of [-1,1]){const spike=mesh(new THREE.ConeGeometry(.1,.65,4),belly,d,-1.05,1.1,s*.15);spike.rotation.z=-1.1;}}
const legs=[];for(const s of [-1,1])for(const xPos of [-.48,.45]){const leg=new THREE.Group();leg.position.set(xPos,.72,s*.25);d.add(leg);cylinder(leg,0,-.28,0,.15,.2,.57,skin);legs.push(leg);}const tail=mesh(new THREE.ConeGeometry(.24,1.4,7),skin,d,-1.15,1.05,0);tail.rotation.z=Math.PI/2;
}
const eyeMat=mat(0x171b17);for(const s of [-1,1])ellipsoid(d,1.08,1.78,s*.2,.055,.06,.045,eyeMat);
return {species,group,body:d,state:['rex','raptor','pteranodon'].includes(species)?'patrol':'graze',health:species==='rex'?100:species==='raptor'?45:120,attack:species==='rex'?24:species==='raptor'?12:16,speed:species==='rex'?2.1:species==='raptor'?3.2:1.1,origin:x,phase:Math.random()*8,alert:false,cd:0,legs:[],alive:true};}
const speciesList=[['rex',47,0],['raptor',-32,3],['raptor',71,1],['triceratops',-54,0],['stegosaurus',24,-1],['brachiosaurus',97,-5],['pteranodon',-14,-7]];for(const [s,x,z] of speciesList)dinos.push(makeDino(s,x,z));

