const speciesList=[['rex',47,0],['raptor',-32,3],['raptor',71,1],['triceratops',-54,0],['stegosaurus',24,-1],['brachiosaurus',97,-5],['pteranodon',-14,-7]];for(const [s,x,z] of speciesList)dinos.push(makeDino(s,x,z));

const state={started:false,paused:false,panel:null,health:100,hunger:82,thirst:76,stamina:100,temp:36.8,day:0,time:6.7,elapsed:0,inventory:{wood:0,stone:0,leaves:0,fiber:0,berries:0,meat:0,bones:0,arrows:0,bandage:0,spear:1,axe:0,bow:0,torch:0,campfire:0,wall:0,trap:0,crate:0},weapon:'spear',weaponDurability:18,selected:0,mission:0,missionProgress:0,weather:'clear',rain:0,attackCd:0,interactCd:0,buildMode:false,buildGhost:null,killCount:0,volume:.38,injury:0};
const recipes=[{id:'axe',name:'Stone axe',icon:'⚒',desc:'A rough stone head lashed to a hardwood haft.',cost:{wood:3,stone:2,fiber:1}},{id:'spear',name:'Stone-tipped spear',icon:'↗',desc:'Reach further, strike harder. Keeps predators at a distance.',cost:{wood:2,stone:1,fiber:1}},{id:'bow',name:'Survivor bow',icon:'⌁',desc:'A flexible branch and twisted cord. Requires arrows.',cost:{wood:3,fiber:3}},{id:'arrows',name:'Stone arrows ×3',icon:'➶',desc:'Jagged flint points wrapped in fiber.',cost:{wood:1,stone:1,fiber:1},amount:3},{id:'bandage',name:'Field bandage',icon:'✚',desc:'Clean leaves and fiber help close wounds.',cost:{leaves:2,fiber:2}},{id:'torch',name:'Resin torch',icon:'♨',desc:'A little light makes the dark less dangerous.',cost:{wood:2,fiber:1}},{id:'campfire',name:'Campfire kit',icon:'♨',desc:'A safe place to cook and recover. Place with B.',cost:{wood:5,stone:3}},{id:'wall',name:'Timber wall',icon:'▤',desc:'A sturdy defensive panel. Place with B.',cost:{wood:6,fiber:2}},{id:'trap',name:'Snare trap',icon:'⌘',desc:'A simple trap that can slow a small predator.',cost:{wood:3,fiber:3}},{id:'crate',name:'Storage crate',icon:'▣',desc:'A secure field cache for gathered supplies.',cost:{wood:5,fiber:2}}];
const keys={};const shell=document.querySelector('#game-shell');const toastEl=document.querySelector('#toast');let toastTimer;
function toast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2300)}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);const aspect=w/h;const viewH=h<600?16:18;camera.left=-viewH*aspect/2;camera.right=viewH*aspect/2;camera.top=viewH/2;camera.bottom=-viewH/2;camera.updateProjectionMatrix();}
addEventListener('resize',resize);resize();
function addToInventory(type,n=1){state.inventory[type]=(state.inventory[type]||0)+n;updateHUD()}
function canPay(cost){return Object.entries(cost).every(([k,n])=>(state.inventory[k]||0)>=n)}
function pay(cost){for(const [k,n] of Object.entries(cost))state.inventory[k]-=n}
function makeSlots(){const entries=[['spear','↗'],['axe','⚒'],['bow','⌁'],['berries','●'],['bandage','✚'],['torch','♨']];document.querySelector('#hotbar').innerHTML=entries.map(([key,icon],i)=>`<div class="slot ${i===state.selected?'selected':''}" data-slot="${i}"><kbd>${i+1}</kbd><span class="slot-icon">${icon}</span><small>${key==='spear'?state.weaponDurability:state.inventory[key]||0}</small></div>`).join('');document.querySelectorAll('.slot').forEach(el=>el.onclick=()=>selectSlot(+el.dataset.slot));}
function selectSlot(i){state.selected=i;const map=['spear','axe','bow','berries','bandage','torch'];state.weapon=map[i];document.querySelectorAll('.slot').forEach((el,n)=>el.classList.toggle('selected',n===i));document.querySelector('#weapon-label').innerHTML=`${state.weapon.toUpperCase()} <i>•</i> ${state.weapon==='spear'?`${state.weaponDurability} / 20`:(state.inventory[state.weapon]||0)}`;}
function updateHUD(){for(const [key,val] of [['health',state.health],['hunger',state.hunger],['thirst',state.thirst],['stamina',state.stamina]]){document.querySelector(`#${key}-bar`).style.width=`${Math.max(0,val)}%`;document.querySelector(`#${key}-value`).textContent=Math.round(val)}document.querySelector('#temp-value').textContent=state.temp.toFixed(1)+'°';document.querySelector('#temp-bar').style.left=`${Math.max(0,Math.min(100,(state.temp-34)*18))}%`;document.querySelector('#condition').textContent=state.health<30?'CRITICAL':state.injury>0?'INJURED':state.temp>38?'OVERHEAT':'STABLE';document.querySelector('#weapon-label').innerHTML=`${state.weapon.toUpperCase()} <i>•</i> ${state.weapon==='spear'?`${state.weaponDurability} / 20`:(state.inventory[state.weapon]||0)}`;makeSlots();updateMission();}
function updateMission(){const stages=[['A PLACE TO BEGIN','Gather wood and stone. The island won’t wait.'],['MAKE IT USEFUL','Craft a stone spear to keep danger at arm’s length.'],['FIND A SAFE PLACE','Make a campfire. Night comes quickly here.'],['THE OLD STATION','Reach the abandoned research station. Something is still powered.']];const [title,copy]=stages[Math.min(3,state.mission)];document.querySelector('#mission-title').textContent=title;document.querySelector('#mission-copy').textContent=copy;document.querySelector('#mission-count').textContent=`0${Math.min(4,state.mission+1)} / 04`;document.querySelector('#mission-progress').style.width=`${Math.min(100,state.missionProgress)}%`;}
function progressMission(amount){state.missionProgress=Math.min(100,state.missionProgress+amount);if(state.missionProgress>=100&&state.mission<3){state.mission++;state.missionProgress=0;toast(['','FIELD NOTE: A SPEAR COULD SAVE YOUR LIFE.','FIELD NOTE: FIRE MEANS SHELTER.','FIELD NOTE: THE STATION IS EAST.'][state.mission]||'OBJECTIVE COMPLETE');}updateMission()}
makeSlots();updateHUD();

let nearest=null;
function findNearest(){let best=3.7;nearest=null;for(const r of resources){if(!r.active)continue;const d=Math.hypot(r.x-player.position.x,(r.z||0)-player.position.z);if(d<best){best=d;nearest={kind:'resource',obj:r,dist:d}}}if(player.position.x>116&&player.position.x<127&&Math.abs(player.position.z)<5&&best>3){nearest={kind:'terminal',dist:4};best=4}if(nearest){document.querySelector('#interaction').classList.add('show');document.querySelector('#interact-title').textContent=nearest.kind==='terminal'?'ACCESS RESEARCH TERMINAL':({wood:'GATHER BRANCH',stone:'COLLECT STONE',berries:'GATHER BERRIES',fiber:'HARVEST FIBER',crate:'OPEN SUPPLY CACHE'}[nearest.obj.type]||'INTERACT');document.querySelector('#interact-detail').textContent=nearest.kind==='terminal'?'Power is still running • 118m':`${nearest.obj.type==='crate'?'Abandoned cache':nearest.obj.type} • ${nearest.dist.toFixed(1)}m`}else document.querySelector('#interaction').classList.remove('show');}
function interact(){if(!state.started||state.paused||state.panel)return;if(nearest?.kind==='resource'){const r=nearest.obj;if(r.type==='wood'){addToInventory('wood',2);progressMission(20);toast('GATHERED · +2 WOOD')}if(r.type==='stone'){addToInventory('stone',1);progressMission(25);toast('GATHERED · +1 STONE')}if(r.type==='berries'){addToInventory('berries',2);addToInventory('leaves',1);toast('GATHERED · WILD BERRIES + LEAVES')}if(r.type==='fiber'){addToInventory('fiber',2);addToInventory('leaves',1);toast('GATHERED · FIBER + LEAVES')}if(r.type==='crate'){addToInventory('arrows',3);addToInventory('bandage',1);addToInventory('meat',2);toast('SUPPLY CACHE · ARROWS, RATIONS, BANDAGE')}r.active=false;world.remove(r.group);nearest=null;document.querySelector('#interaction').classList.remove('show');state.interactCd=.35;}else if(nearest?.kind==='terminal'){openPanel('research');toast('RESEARCH LOG RECOVERED · RECIPE UNLOCKED');state.mission=3;state.missionProgress=100;updateMission();}}
function nearestTarget(){return dinos.filter(d=>d.alive&&Math.abs(d.group.position.x-player.position.x)<3.7&&Math.abs(d.group.position.z-player.position.z)<2.8).sort((a,b)=>Math.abs(a.group.position.x-player.position.x)-Math.abs(b.group.position.x-player.position.x))[0]}
