function damageDino(d,amount){d.health-=amount;d.alert=true;d.state='chase';if(d.health<=0){d.alive=false;d.group.rotation.z=Math.PI/2;state.killCount++;addToInventory('meat',d.species==='rex'?4:2);addToInventory('bones',1);progressMission(12);toast('DINOSAUR DOWN · MEAT + BONES');setTimeout(()=>world.remove(d.group),1800)}}

function openPanel(type){if(type==='pause'){state.paused=true;document.querySelector('#pause-panel').classList.remove('hidden');return}if(type==='map'){state.panel='map';document.querySelector('#map-panel').classList.remove('hidden');return}state.paused=true;state.panel=type;const panel=document.querySelector('#game-panel');panel.classList.remove('hidden');const title=document.querySelector('#panel-title'),kicker=document.querySelector('#panel-kicker'),content=document.querySelector('#panel-content');if(type==='inventory'){title.textContent='INVENTORY';kicker.textContent='FIELD EQUIPMENT';renderInventory(content)}else if(type==='craft'){title.textContent='CRAFTING';kicker.textContent='FIELD FABRICATION';renderCraft(content)}else if(type==='research'){title.textContent='RECOVERED LOG';kicker.textContent='RESEARCH STATION 04';content.innerHTML='<div class="research-log"><p style="color:#cbd8a1;font:700 10px DM Sans;letter-spacing:1px">FIELD NOTE 04 // 19:42</p><p style="color:#d2d7c8;font-size:12px;line-height:1.8">The animals are moving inland. Raptor activity is unusually high near the river. We found a way to reinforce the old perimeter, but the power grid is failing. If anyone finds this — the extraction beacon is at the north ridge.</p><div class="inventory-item"><span class="item-icon">⌁</span><span class="item-name">RECIPE UNLOCKED<small>Reinforced wall · craft from wood + stone</small></span><span class="item-count">✓</span></div></div>'}document.querySelector('#panel-footer-right').textContent=type==='craft'?'RECIPES AVAILABLE: '+recipes.filter(r=>canPay(r.cost)).length:'SURVIVAL SYSTEMS ONLINE';}
function renderInventory(root){const labels={wood:['⌁','Hardwood'],stone:['◈','Flint stone'],leaves:['❧','Broad leaves'],fiber:['〰','Plant fiber'],berries:['●','Wild berries'],meat:['◆','Raw meat'],bones:['⌖','Bone'],arrows:['➶','Stone arrows'],bandage:['✚','Field bandage'],spear:['↗','Stone spear'],axe:['⚒','Stone axe'],bow:['⌁','Survivor bow'],torch:['♨','Resin torch'],campfire:['♨','Campfire kit'],wall:['▤','Timber wall'],trap:['⌘','Snare trap'],crate:['▣','Storage crate']};root.innerHTML=`<div class="inventory-grid">${Object.entries(state.inventory).map(([key,n])=>`<div class="inventory-item"><span class="item-icon">${labels[key]?.[0]||'◈'}</span><span class="item-name">${labels[key]?.[1]||key}<small>${n>0?'Ready to use':'Not carried'}</small></span><span class="item-count">×${n}</span>${['berries','meat','bandage'].includes(key)&&n>0?`<button class="action-button" data-use="${key}">${key==='bandage'?'USE':'EAT'}</button>`:''}</div>`).join('')}</div>`;root.querySelectorAll('[data-use]').forEach(btn=>btn.onclick=()=>{const k=btn.dataset.use;if(!state.inventory[k])return;if(k==='bandage'){state.inventory.bandage--;state.health=Math.min(100,state.health+32);state.injury=Math.max(0,state.injury-1);toast('BANDAGE USED · HEALTH RESTORED')}else if(k==='berries'){state.inventory.berries--;state.hunger=Math.min(100,state.hunger+16);toast('WILD BERRIES EATEN')}else{state.inventory.meat--;state.hunger=Math.min(100,state.hunger+28);toast('RAW MEAT EATEN · RISK OF SICKNESS')}updateHUD();renderInventory(root)});}
function renderCraft(root){root.innerHTML=`<div class="panel-tabs"><button class="panel-tab active" data-cat="all">ALL RECIPES</button><button class="panel-tab" data-cat="tools">TOOLS</button><button class="panel-tab" data-cat="survival">SURVIVAL</button><button class="panel-tab" data-cat="building">BUILDING</button></div><div class="craft-list">${recipes.map((r,i)=>`<div class="craft-item" data-recipe="${r.id}"><span class="craft-symbol">${r.icon}</span><span class="craft-name">${r.name}<small>${r.desc}</small><div class="recipe-cost">${Object.entries(r.cost).map(([k,n])=>`${k.toUpperCase()} ${n}`).join('　·　')}</div></span><button class="craft-button" ${canPay(r.cost)?'':'disabled'} data-craft="${r.id}">${state.inventory[r.id]>0&&['axe','spear','bow'].includes(r.id)?'OWNED':'CRAFT'}</button></div>`).join('')}</div>`;root.querySelectorAll('[data-craft]').forEach(btn=>btn.onclick=()=>craftItem(btn.dataset.craft));root.querySelectorAll('[data-cat]').forEach(btn=>btn.onclick=()=>{root.querySelectorAll('.panel-tab').forEach(t=>t.classList.remove('active'));btn.classList.add('active');root.querySelectorAll('.craft-item').forEach((el,i)=>{const cat=btn.dataset.cat;const group=i<4?'tools':i<6?'survival':'building';el.style.display=cat==='all'||cat===group?'grid':'none'})});}
function craftItem(id){const r=recipes.find(x=>x.id===id);if(!r||!canPay(r.cost)){toast('NOT ENOUGH RESOURCES');return}if(['axe','spear','bow'].includes(id)&&state.inventory[id]>0){toast('YOU ALREADY HAVE THIS');return}pay(r.cost);state.inventory[id]=(state.inventory[id]||0)+(r.amount||1);if(id==='spear'&&state.mission===1)progressMission(100);if(id==='campfire'&&state.mission===2)state.missionProgress=50;toast(`CRAFTED · ${r.name.toUpperCase()}`);updateHUD();renderCraft(document.querySelector('#panel-content'));}
function closePanels(){document.querySelectorAll('.panel').forEach(p=>p.classList.add('hidden'));state.panel=null;state.paused=false}
function buildToggle(){const possible=['campfire','wall','trap','crate'];const what=possible.find(k=>state.inventory[k]>0);if(!what){toast('NO BUILDABLE ITEMS · CRAFT A KIT FIRST');return}if(!state.buildMode){state.buildMode=what;const geom=what==='wall'?new THREE.BoxGeometry(2.4,2.1,.35):new THREE.CylinderGeometry(.7,.8,.25,8);state.buildGhost=new THREE.Mesh(geom,new THREE.MeshStandardMaterial({color:0xcddf98,transparent:true,opacity:.43,wireframe:true}));world.add(state.buildGhost);toast(`PLACE ${what.toUpperCase()} · CLICK TO CONFIRM · ESC TO CANCEL`)}else cancelBuild()}
function cancelBuild(){if(state.buildGhost)world.remove(state.buildGhost);state.buildGhost=null;state.buildMode=false}
function placeBuild(){if(!state.buildMode)return;const x=player.position.x+(player.rotation.y===Math.PI/2?2:-2),z=player.position.z;const type=state.buildMode;const root=new THREE.Group();root.position.set(Math.round(x/1.2)*1.2,0,z);world.add(root);if(type==='wall'){box(root,0,1.1,0,2.4,2.2,.35,materials.wood);for(let i=-1;i<=1;i++)box(root,i*.75,1.1,.2,.08,2.25,.08,materials.bark)}else if(type==='campfire'){for(let i=0;i<3;i++){const log=cylinder(root,(i-1)*.18,.15,0,.08,.08,1.1,materials.wood);log.rotation.z=Math.PI/2;log.rotation.y=i*1.05}ellipsoid(root,0,.42,0,.18,.3,.18,materials.camp);const light=new THREE.PointLight(0xff9e4b,1.4,8);light.position.y=1;root.add(light)}else if(type==='trap'){const c=mesh(new THREE.TorusGeometry(.45,.055,6,12),materials.metal,root,0,.08,0);c.rotation.x=Math.PI/2;for(let i=0;i<3;i++)box(root,0,.05,(i-1)*.25,.7,.08,.06,materials.wood)}else{box(root,0,.5,0,.9,1,.8,materials.wood);box(root,0,1.02,0,1,.1,.9,materials.bark)}state.inventory[type]--;cancelBuild();progressMission(type==='campfire'?50:0);if(type==='campfire')state.mission=3;toast(`${type.toUpperCase()} PLACED · BASE SECURED`);updateHUD()}

