function updateDinos(dt){for(const d of dinos){if(!d.alive)continue;d.phase+=dt*(d.state==='chase'?8:2.4);d.cd=Math.max(0,d.cd-dt);const dx=player.position.x-d.group.position.x,dist=Math.abs(dx);const predator=d.species==='rex'||d.species==='raptor';if(predator&&dist<(d.species==='rex'?12:8.5)&&Math.abs(player.position.z-d.group.position.z)<5){d.alert=true;d.state='chase'}if(d.state==='chase'&&d.alert){if(dist>1.8){const pace=d.speed*(d.species==='rex'?.72:1);d.group.position.x+=Math.sign(dx)*pace*dt;d.group.rotation.y=dx<0?Math.PI:0}else if(d.cd<=0&&state.started&&!state.paused&&!death){d.cd=d.species==='rex'?1.6:1.15;hurtPlayer(d.attack,d.species==='rex'?'TYRANNOSAURUS':'RAPTOR');}}else{d.state=predator?'patrol':'graze';const drift=Math.sin(d.phase*.35)*.24;d.group.position.x+=drift*dt;if(Math.abs(d.group.position.x-d.origin)>8)d.origin=d.group.position.x;d.group.rotation.y=drift<0?Math.PI:0;}const bob=Math.sin(d.phase)*.025;d.body.position.y=bob;if(d.species==='pteranodon')d.group.position.y=3.5+Math.sin(d.phase*.7)*.55;if(d.species==='rex'||d.species==='raptor'){const gap=Math.abs(d.group.position.x-player.position.x);if(gap<22&&Math.abs(player.position.z-d.group.position.z)<4){document.querySelector('#threat').classList.add('show');threatTimer=1.2}}}}
