weather-copy').innerHTML=state.weather==='rain'?'RAIN SHOWERS <i>•</i> 19°C':'CLEAR SKIES <i>•</i> 24°C'}rainMesh.visible=state.weather==='rain';if(rainMesh.visible){const p=rainGeometry.attributes.position;for(let i=0;i<p.count;i++){p.array[i*3+1]-=dt*15;if(p.array[i*3+1]<0){p.array[i*3+1]=15+Math.random()*4;p.array[i*3]=player.position.x+(Math.random()-.5)*60;p.array[i*3+2]=(Math.random()-.5)*22}}p.needsUpdate=true}updateHUD()}
